<script setup>
import {ref,onMounted,computed,watch} from 'vue'
import {request as directRequest,upload as directUpload} from './client'
function request(module,method,args={},verb='POST'){return bridge.value?directRequest('public_student','action',{module,method,args}):directRequest(module,method,args,verb)}
function upload(module,method,body){if(bridge.value){body.append('invoice',form.value.invoice);return directUpload('public_student','upload_proof',body)}return directUpload(module,method,body)}
import WhatsAppComposer from './WhatsAppComposer.vue'
import {previewMode} from '../preview/mode'
const props=defineProps({general:Boolean,sharedCampus:Boolean,selectedClass:Object,member:Object,invoices:{type:Array,default:()=>[]},rooms:{type:Array,default:()=>[]}}),emit=defineEmits(['changed'])
const bridge=computed(()=>props.member.role==='Student'&&(props.general||props.sharedCampus))
const loadedInvoices=ref(null),invoices=computed(()=>loadedInvoices.value??props.invoices)
let paymentIntent='';try{paymentIntent=sessionStorage.getItem('sisu-payment-invoice')||''}catch{}
const reasons=['Slip is unclear or unreadable','Incorrect payment amount','Payment not received','Incorrect bank account','Duplicate or previously used slip','Wrong class or invoice','Other']
const copied=ref(false),success=ref('')
const analysis=ref(null),bank=ref(null)
let bankSequence=0
async function loadBank(){const sequence=++bankSequence;bank.value=null;copied.value=false;const row=invoices.value.find(i=>i.name===form.value.invoice);if(row)try{const result=await request('class_keys','bank_details',{classroom:row.classroom},'GET');if(sequence===bankSequence)bank.value=result}catch(e){error.value=e.message}}
async function copyBank(){try{await navigator.clipboard.writeText(bank.value.instructions);copied.value=true}catch{error.value='Select and copy the bank details manually.'}}
const page=ref(0),reviewMode=ref('View'),whatsapp=ref(null)
const rows=ref([]),error=ref(''),busy=ref(false),selected=ref(null),file=ref(null),proofName=ref(''),tab=ref('Pending')
const form=ref({invoice:'',reference:'',amount:'',transfer_date:new Date().toLocaleDateString('en-CA'),access_kind:'Month',starts_at:'',ends_at:'',note:'',rejection_reason:''})
const configuredDuration=computed(()=>{const r=props.rooms.find(r=>r.name===selected.value?.classroom);return r?.access_duration_days||!!r?.programme})
const student=computed(()=>props.member.role==='Student'),filtered=computed(()=>rows.value.filter(r=>tab.value==='All'||r.status===tab.value))
const roomName=id=>props.rooms.find(r=>r.name===id)?.title||id,money=n=>'LKR '+new Intl.NumberFormat('en-LK').format((n||0)/100)
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){
 if(student.value){
  if(bridge.value){const data=await directRequest('public_student','billing',{...(paymentIntent?{invoice:paymentIntent}:{}),...(props.selectedClass?.name?{classroom:props.selectedClass.name}:{})},'GET');loadedInvoices.value=data.invoices;rows.value=data.slips}
  else{const [bills,slips]=await Promise.all([directRequest('api','invoices',{...(paymentIntent?{preferred_invoice:paymentIntent}:{}),...(props.selectedClass?.name?{preferred_classroom:props.selectedClass.name}:{})}),request('commercial','slips',{page:page.value})]);loadedInvoices.value=bills;rows.value=slips}
  const due=invoices.value.filter(i=>i.status==='Unpaid')
  const room=props.selectedClass
  const match=due.find(i=>i.name===paymentIntent)||due.find(i=>room&&(i.classroom===room.name||room.programme&&i.programme===room.programme))||due.find(i=>i.name===form.value.invoice)||(due.length===1?due[0]:null)
  if(match){form.value.invoice=match.name;pickInvoice()}else if(!due.some(i=>i.name===form.value.invoice)){form.value.invoice='';form.value.amount='';bank.value=null}
 }else rows.value=await request('commercial','slips',{page:page.value})
}
function startReview(row,mode='View'){analysis.value=null;proofName.value='';reviewMode.value=mode;form.value.rejection_reason='';selected.value=row;const room=props.rooms.find(r=>r.name===row.classroom);form.value.note='';form.value.starts_at='';form.value.access_kind=room?.programme?'Course':room?.paid_access_kind||'Month';form.value.ends_at=room?.paid_access_end?.replace(' ','T')||''}
function pickInvoice(){form.value.amount=invoices.value.find(i=>i.name===form.value.invoice)?.amount||'';loadBank()}
async function submit(){await run(async()=>{if(!file.value)throw Error('Choose a slip');if(file.value.size>5*1024*1024)throw Error('Slip must be at most 5 MB');const body=new FormData();body.append('file',file.value);const f=previewMode?{name:file.value.name}:await upload('commercial','upload_proof',body);await request('commercial','submit_slip',{...form.value,proof:f.name});paymentIntent='';try{sessionStorage.removeItem('sisu-payment-invoice')}catch{};await load();file.value=null;tab.value='Pending';success.value='Slip submitted. Your payment is pending review by your teacher or institute.';emit('changed')})}
async function review(decision){await run(async()=>{await request('commercial','review_slip',{...form.value,name:selected.value.name,decision});selected.value=null;await load();emit('changed')})}
const submitted=value=>value?new Date(value.includes('T')||value.endsWith('Z')?value:value.replace(' ','T')+'+05:30').toLocaleString('en-LK',{timeZone:'Asia/Colombo',dateStyle:'medium',timeStyle:'short'}):'Not recorded'
function showProof(row){if(previewMode){proofName.value='Preview proof: fictional transfer, not a bank confirmation.';return}window.open('/api/method/institute_lms.'+(bridge.value?'public_student':'commercial')+'.proof?'+new URLSearchParams({name:row.name}),'_blank','noopener')}
function chooseInvoice(row){form.value.invoice=row.name;pickInvoice();document.getElementById('bank-transfer')?.scrollIntoView({behavior:'smooth',block:'start'})}
defineExpose({chooseInvoice})
watch(()=>[props.selectedClass,invoices.value],()=>{
 const room=props.selectedClass;if(!room||paymentIntent)return
 const invoice=invoices.value.find(i=>i.status==='Unpaid'&&(i.classroom===room.name||(room.programme&&i.programme===room.programme)))
 if(invoice&&form.value.invoice!==invoice.name){form.value.invoice=invoice.name;pickInvoice()}
},{immediate:true})
onMounted(()=>run(load))
</script>
<template><section id="bank-transfer" class="panel bank-payments"><div class="section-heading"><div><h2>{{student?'Pay by bank transfer':'Bank payment reviews'}}</h2><p>{{student?'Choose your class and upload your bank slip. The fee is filled in automatically. Your teacher or institute checks their bank account before approval. After approval, use your personal enrollment key to unlock the class.':'Check the money received in your bank account before approving a slip.'}}</p></div><button class="button subtle small" :disabled="busy" @click="run(load)">Refresh</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="success" role="status">{{success}}</p><p v-if="proofName" role="status">{{proofName}}</p>
<p v-if="member.role==='Admin'" class="field-help">Manage receiving bank details in My profile → Bank details for student payments. They apply to every institute class and programme.</p><p v-if="member.role==='Teacher'&&!member.institute_teacher" class="field-help">Manage your receiving bank details in My profile → Bank details for student payments. They apply to all your independent classes.</p><p v-if="student&&!invoices.some(i=>i.status==='Unpaid')" class="field-help">No classes or programmes awaiting payment. Choose Enroll now on a class or programme to start.</p><form v-if="student&&invoices.some(i=>i.status==='Unpaid')" @submit.prevent="submit"><div class="form-row"><label>Class or programme<select v-model="form.invoice" @change="pickInvoice" required><option value="">Choose a class or programme</option><option v-for="i in invoices.filter(i=>i.status==='Unpaid')" :value="i.name">{{i.programme_title||i.classroom_title||roomName(i.classroom)}} · LKR {{i.amount}}</option></select></label><label>Payment amount (LKR)<input v-model="form.amount" readonly type="number" min="0.01" step="0.01" required></label></div><div class="form-row"><label>Transfer reference<input v-model="form.reference" required maxlength="140"></label><label>Transfer date<input v-model="form.transfer_date" type="date" required></label></div><div v-if="bank"><h3>{{bank.recipient}}</h3><pre style="white-space:pre-wrap">{{bank.instructions||'Contact your provider for bank details before paying.'}}</pre><button type="button" class="button subtle" v-if="bank.instructions" @click="copyBank">{{copied?'Copied!':'Copy bank details'}}</button></div><label>Bank slip · PDF, image, Word or text · maximum 5 MB<input type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.txt" required @change="file=$event.target.files[0]"></label><p class="muted">Transfer only to the bank account confirmed by your teacher or institute. Uploading a slip does not grant access.</p><button class="button primary" :disabled="busy||!form.invoice">Submit slip for review</button></form>
<div class="tabs"><button v-for="s in ['Pending','Approved','Rejected','All']" :class="{selected:tab===s}" @click="tab=s">{{s}} <span v-if="s==='Pending'">({{rows.filter(r=>r.status==='Pending').length}})</span></button></div><div class="table-wrap review-table"><table><thead><tr><th>Student</th><th>Class</th><th>Submitted</th><th>Transfer / amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.name"><td><strong>{{r.student_name||r.student}}</strong><small>LMS ID · {{r.student_lms_id||r.student}}</small><small>{{r.contact_number||'Contact number not added'}}</small></td><td>{{roomName(r.classroom)}}</td><td>{{submitted(r.submitted_at||r.creation)}}<small>Sri Lanka time</small></td><td><strong>{{money(r.claimed_minor)}}</strong><small>{{r.reference}} · {{r.transfer_date}}</small></td><td><span class="badge" :class="r.status==='Approved'?'green':r.status==='Rejected'?'peach':'violet'">{{r.status}}</span><small v-if="r.rejection_reason">{{r.rejection_reason}}</small></td><td><div class="review-actions"><button class="button subtle small" @click="startReview(r)">View</button><template v-if="!student&&r.status==='Pending'"><button class="button primary small" @click="startReview(r,'Approve')">Approve</button><button class="button subtle small reject-action" @click="startReview(r,'Reject')">Reject</button></template></div></td></tr></tbody></table><p v-if="!filtered.length" class="empty-mini">No {{tab==='All'?'':tab.toLowerCase()}} bank slips on this page.</p></div><div class="inline"><button v-if="page>0" class="button subtle small" @click="page--;run(load)">Newer submissions</button><button v-if="rows.length===50" class="button subtle small" @click="page++;run(load)">Older submissions</button></div>
<div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal bank-review" role="dialog" aria-modal="true" aria-label="Review bank payment"><header class="section-heading"><h2>{{reviewMode==='View'?'Payment submission':reviewMode+' bank payment'}}</h2><button class="icon-button" aria-label="Close payment review" @click="selected=null">×</button></header><div class="student-review-card"><strong>{{selected.student_name||selected.student}}</strong><span>LMS ID · {{selected.student_lms_id||selected.student}}</span><span>Contact · {{selected.contact_number||'Not added'}}</span><span>Submitted · {{submitted(selected.submitted_at||selected.creation)}} (Sri Lanka time)</span></div><p>{{roomName(selected.classroom)}}<br><strong>{{money(selected.claimed_minor)}}</strong> · {{selected.reference}} · {{selected.transfer_date}}</p><button class="button subtle" @click="showProof(selected)">View bank slip</button><button v-if="!student" class="button subtle" :disabled="busy" @click="run(async()=>{analysis=await request('workspace','analyse_slip',{name:selected.name})})">Analyse slip</button><aside v-if="analysis" class="student-review-card"><strong>{{analysis.mode}}</strong><span v-for="(value,key) in analysis.checks">{{key.replaceAll('_',' ')}} · {{value?'Found':'Not confirmed'}}</span><span>Repeated reference: {{analysis.duplicate_reference?'Check for duplicate payment':'None found'}}</span><p>{{analysis.notice}}</p></aside><p v-if="proofName" role="status">{{proofName}}</p><p v-if="selected.review_note">Review note: {{selected.review_note}}</p><p v-if="error" role="alert" class="error">{{error}}</p><template v-if="!student&&selected.status==='Pending'"><div class="tabs"><button :class="{selected:reviewMode==='Approve'}" @click="reviewMode='Approve'">Approve</button><button :class="{selected:reviewMode==='Reject'}" @click="reviewMode='Reject'">Reject</button></div><template v-if="reviewMode==='Approve'"><p v-if="configuredDuration" class="field-help">Approved access uses the duration saved on this class or programme. Its end is calculated from the access start below.</p><label v-if="!configuredDuration">Access duration<select v-model="form.access_kind"><option v-for="k in ['Day','Week','Month','Year','Session','Course','Custom']">{{k}}</option></select></label><label>Access starts (Sri Lanka time; leave empty for now)<input type="datetime-local" v-model="form.starts_at"></label><label v-if="!configuredDuration&&['Session','Course','Custom'].includes(form.access_kind)">Access ends (Sri Lanka time)<input type="datetime-local" v-model="form.ends_at" required></label><label>How did you verify the bank payment?<textarea v-model="form.note" required maxlength="800" placeholder="Check the received amount in your bank account and record the confirmation."/></label><button class="button primary" :disabled="busy||!form.note.trim()" @click="review('Approved')">Confirm payment & approve access</button></template><template v-if="reviewMode==='Reject'"><label>Rejection reason<select v-model="form.rejection_reason" required><option value="">Choose a reason</option><option v-for="reason in reasons" :key="reason">{{reason}}</option></select></label><label>{{form.rejection_reason==='Other'?'Explain the reason':'Additional details for the student (optional)'}}<textarea v-model="form.note" maxlength="800" :required="form.rejection_reason==='Other'"/></label><button class="button primary" :disabled="busy||!form.rejection_reason||(form.rejection_reason==='Other'&&!form.note.trim())" @click="review('Rejected')">Reject & notify student</button></template></template><p class="field-help">Institute class payments belong to the institute. Independent class payments belong to the teacher. Approval records the received payment; it does not transfer money.</p></section></div><WhatsAppComposer v-if="whatsapp" :rooms="rooms" :initial-class="whatsapp.classroom" :student="whatsapp.student" :slip="whatsapp.name" @close="whatsapp=null"/>
</section></template>
<style scoped>.bank-payments{margin-bottom:24px;border-color:#ece5f6;border-radius:18px;box-shadow:0 8px 24px rgba(32,20,56,.04)}.bank-payments label{display:grid;gap:8px;margin:14px 0;font-size:13px;font-weight:600;color:var(--student-ink,#2b213d)}.bank-payments input,.bank-payments select,.bank-payments textarea{padding:12px 14px;border:1px solid #e4dcf0;border-radius:11px;background:var(--surface,#faf8fd);color:inherit;font:inherit;transition:border-color .15s,box-shadow .15s}.bank-payments :is(input,select,textarea):focus{border-color:#56288d;box-shadow:0 0 0 3px rgba(86,40,141,.1);outline:0}.bank-payments form{margin:20px 0 28px;max-width:850px}.bank-payments .tabs{margin-top:24px}.bank-payments .tabs button.selected{background:#56288d!important;color:#fff!important;border-radius:999px;padding:8px 15px}.bank-review{padding:28px;border-radius:20px}.student-review-card{display:grid;gap:10px;padding:18px;background:#f5f0fc;border:1px solid #e6dcf5;border-radius:14px}.student-review-card span{font-size:12px}.review-actions{display:flex;flex-wrap:wrap;gap:5px}.review-table table{min-width:920px}.review-table td{vertical-align:top}.review-table td strong{display:block}.reject-action{color:#922d4f}.bank-review label{display:grid;gap:8px;margin:16px 0}.bank-review p{line-height:1.8}.bank-payments td .button{margin:3px}.bank-payments td small{display:block;margin-top:5px}.bank-payments .form-row{display:grid;grid-template-columns:1fr 1fr;gap:18px}@media(max-width:650px){.bank-payments .form-row{grid-template-columns:1fr;gap:0}.bank-review{padding:20px}}</style>
